.pui-text-field {
  width:100%;
  color: var(--pui-text, #31333e);
  box-sizing: border-box;
  font-size: 1rem;
  * {
    box-sizing: border-box;
  }
  &__label-block {
    font-size: .875rem;
    display: flex;
    justify-content: space-between;
    margin-bottom: .25rem;
  }
  &__label-secondary {
    color: var(--pui-text-secondary, #63636e);
  }
  &__input-block {
    display:flex;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    .pui-text-field__input-prefix, .pui-text-field__input-suffix {
      height: 100%;
      display: flex;
      align-items: center;
    }
    input {
      width:100%;
      font: inherit;
      color: inherit;
      height: 100%;
      border: 0;
      outline: 0;
      box-shadow: none;
      background-color: inherit;
      &:disabled {
        background-color: inherit;
        cursor: not-allowed;
      }
      &::placeholder {
        color: var(--pui-input-placeholder, #adb5bd);
      }
    }
  }
  &__message-block {
    font-size: .75rem;
    margin-top: .25em;
    color: var(--pui-text-secondary, #63636e);
  }

  /* Textfield size styles */
  &--sm {
    .pui-text-field__label-block {
      font-size: .75rem;
    }
    .pui-text-field__input-block {
      height: 2rem;
      font-size: .875rem;
      .pui-text-field__input-prefix {
        padding-left: .5rem;
      }
      .pui-text-field__input-suffix {
        padding-right: .5rem;
      }
      input {
        padding:0 .5rem;
      }
    }
    .pui-text-field__message-block {
      font-size: .65rem;
    }
    &.pui-text-field--line {
      .pui-text-field__input-block {
        height: 1.625rem;
        .pui-text-field__input-prefix {
          padding-right: .5rem;
        }
        .pui-text-field__input-suffix {
          padding-left: .5rem;
        }
      }
    }
  }
  &--md {
    .pui-text-field__input-block {
      height: 2.5rem;
      .pui-text-field__input-prefix {
        padding-left: .75rem;
      }
      .pui-text-field__input-suffix {
        padding-right: .75rem;
      }
      input {
        padding:0 .75rem;
      }
    }
    &.pui-text-field--line {
      .pui-text-field__input-block {
        height: 1.875rem;
        .pui-text-field__input-prefix {
          padding-right: .75rem;
        }
        .pui-text-field__input-suffix {
          padding-left: .75rem;
        }
      }
    }
  }
  &--lg {
    .pui-text-field__input-block {
      height: 3rem;
      font-size: 1.125rem;
      .pui-text-field__input-prefix {
        padding-left: 1rem;
      }
      .pui-text-field__input-suffix {
        padding-right: 1rem;
      }
