      .pui-text-field__input-block {
        height: 2rem;
        .pui-text-field__input-prefix {
          padding-right: 1rem;
        }
        .pui-text-field__input-suffix {
          padding-left: 1rem;
        }
      }
    }
  }

  /* Textfield variant styles */
  &--outlined {
    .pui-text-field__input-block {
      border: 1px solid var(--pui-soft-border, #dadce3);
      border-radius: 5px;
      overflow: hidden;
    }
  }
  &--line {
    .pui-text-field__input-block {
      border-bottom: 1px solid var(--pui-soft-border, #dadce3);
      overflow: hidden;
      margin: 0 0 .3rem;
      background-color: transparent;
      .pui-text-field__input-prefix {
        padding-left: 0;
      }
      .pui-text-field__input-suffix {
        padding-right: 0;
      }
      input {
        padding:0;
      }
    }
  }
  &--filled {
    .pui-text-field__input-block {
      border: 1px solid var(--pui-input-filler, #f0f0f2);
      border-radius: 5px;
      overflow: hidden;
      background-color: var(--pui-input-filler, #f0f0f2);
      input {
        background-color: inherit;
      }
    }
  }

  /* Textfield dark mode styles */
