      .pui-text-field__input-block {
        border-color: var(--pui-input-filler-dark, #313437);
        background-color: var(--pui-input-filler-dark, #313437);
      }
      &.pui-text-field--error {
        .pui-text-field__input-block {
          background-color: var(--pui-error-darken, #230b0b);
        }
      }
    }
  }

  /* Textfield state styles */
  &:hover {
    &:not(.pui-text-field--focus, .pui-text-field--error, .pui-text-field--disabled) {
      .pui-text-field__input-block:hover {
        border-color: var(--pui-border, #c3c7d0);
      }
    }
    .pui-dark-mode &:not(.pui-text-field--focus, .pui-text-field--error, .pui-text-field--disabled),
    &.pui-text-field-dark:not(.pui-text-field--focus, .pui-text-field--error, .pui-text-field--disabled) {
      .pui-text-field__input-block:hover {
        border-color: var(--pui-border-in-dark, #43474a);
      }
    }
  }
  &.pui-text-field--disabled {
    .pui-text-field__input-block {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }
  &.pui-text-field--focus {
    .pui-text-field__input-block {
      border-color: var(--pui-info, #008DDA);
      box-shadow: 0 0 0 .5px var(--pui-info, #008DDA);
    }
    &.pui-text-field--line {
      .pui-text-field__input-block {
        box-shadow: none;
        border-bottom-width:1.5px;
      }
    }
  }
  &.pui-text-field--error {
    .pui-text-field__input-block {
      border-color:var(--pui-error, #e74747);
      box-shadow: 0 0 0 .5px var(--pui-error, #e74747);
    }
    &.pui-text-field--line {
      .pui-text-field__input-block {
        box-shadow: none;
        border-bottom-width:1.5px;
      }
    }
    .pui-text-field__message-block {
      .pui-text-field__error-message {
        color: var(--pui-error, #e74747);
      }
    }
    &.pui-text-field--filled {
      .pui-text-field__input-block {
        background-color: var(--pui-error-lighten, #fbe3e3);
      }
    }
  }
}

